package ru.ultimavox.itsm.servicedesk.api;
import io.swagger.v3.oas.annotations.Operation; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import ru.ultimavox.itsm.servicedesk.application.WorkItemQuery; import ru.ultimavox.itsm.servicedesk.domain.WorkItem; import java.util.*;
@RestController @RequestMapping("/api/v1/work-items") class WorkItemController { private final WorkItemQuery query; WorkItemController(WorkItemQuery query){this.query=query;} @GetMapping @Operation(summary="List work items visible to the caller") List<WorkItem> list(Authentication authentication){return query.findVisibleTo(authentication.getName());} }
